mapper.select:
SELECT a.*, c.name as category_name, c.icon as category_icon
FROM account a
LEFT JOIN category c ON a.category_id = c.id
WHERE a.user_id = #{userId}

    AND a.date >= #{startDate}


    AND a.date <= #{endDate}


    AND a.type = #{type}


    AND a.category_id = #{categoryId}

ORDER BY a.date DESC, a.create_time DESC

SELECT c.name, c.icon, SUM(a.amount) as amount
FROM account a
LEFT JOIN category c ON a.category_id = c.id
WHERE a.user_id = #{userId}
AND DATE_FORMAT(a.date, '%Y-%m') = #{month}
AND a.type = #{type}
GROUP BY c.id, c.name, c.icon
ORDER BY amount DESC

SELECT
    SUM(CASE WHEN a.type = 'income' THEN a.amount ELSE 0 END) as totalIncome,
    SUM(CASE WHEN a.type = 'expense' THEN a.amount ELSE 0 END) as totalExpense
FROM account a
WHERE a.user_id = #{userId}
AND DATE_FORMAT(a.date, '%Y') = #{year}
